def components(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));n=0
   while q:
    x,y=q.pop();n+=1
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
      seen.add((a,b));q.append((a,b))
   out.append((n,col,(r,c)))
 return sorted(out,reverse=True)
